public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about a business connection by its identifier; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.BusinessConnection> GetBusinessConnectionAsync(string connectionId = default)
    {

           using var activity =  StartCallActivity("GetBusinessConnectionAsync", typeof(GetBusinessConnection).FullName ?? "GetBusinessConnectionAsync");

           try
           {
             return client.GetBusinessConnectionAsync(connectionId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
